import requests,json,hashlib
from PIL import Image
P=Path(__file__).resolve().parents[1];cats=['quests','buildings','materials','locations'];D={c:json.loads((P/'data'/f'{c}.json').read_text()) for c in cats};I={(c,x['slug']):x for c,arr in D.items() for x in arr};B='https://zombie-island.moy.su/';H={}
for p in (P/'img').rglob('*'):
 if p.is_file():H.setdefault(hashlib.sha256(p.read_bytes()).hexdigest(),str(p.relative_to(P)))
def add(cat,slug,name,page,pic,typ,fields):
 if (cat,slug) in I:return
 r=requests.get(B+pic,timeout=25);r.raise_for_status();im=Image.open(BytesIO(r.content));im.verify();h=hashlib.sha256(r.content).hexdigest();ext={'PNG':'.png','JPEG':'.jpg','GIF':'.gif'}[im.format];path=H.get(h)
 if not path:path=f'img/archive/frost-2014-{slug}-{h[:12]}'+ext;(P/path).write_bytes(r.content);H[h]=path
 x={'slug':slug,'name':name,'category':cat,'type':typ,'purchase':'нет данных','sale':'нет данных','obtain':'нет данных','use':'нет данных','features':'нет данных','versions':'историческая браузерная социальная игра; платформа и редакция уточняются','sources':[{'url':B+page,'label':'Zombie-island: отдельная историческая статья'}],'image':{'path':path,'retrieved_from':B+pic,'attribution':'http://zombicity.info/'+pic,'source_page':B+page,'note':'Исходный файл без перекодирования с альтернативного хоста; совпадение байтов с оригинальной ссылкой не проверено.'},'links':[],'event':'Морозная свежесть и Сказочный лес — декабрь 2014','prior_records':[{'original_id':'frost-2014-'+slug,'original_category':typ,'version':'браузерная игра; платформа не уточнена','date':'декабрь 2014 — дата публикации; дата поздних правок не установлена','fields':fields,'confidence':'Фанатский источник; возможны ошибки, разночтения и изменения редакций.'}]};D[cat].append(x);I[cat,slug]=x
def link(a,b,rel):
 x=I[a];y=I[b]
 if not any(i.get('category')==b[0] and i.get('slug')==b[1] for i in x['links']):x['links'].append({'category':b[0],'slug':b[1],'name':y['name'],'relation':rel})
def upd(k,url,id,fields):
 x=I[k]
 if not any(s['url']==url for s in x['sources']):x['sources'].append({'url':url,'label':'Zombie-island: историческая статья / новость'})
 if not any(r.get('original_id')==id for r in x.setdefault('prior_records',[])):x['prior_records'].append({'original_id':id,'original_category':'Историческое уточнение','version':'браузерная игра; редакция не установлена','date':'30.12.2014 — дата статьи, последующие правки не датированы','fields':fields,'confidence':'Фанатский источник; условия и версии требуют независимой проверки.'})
rows=[('quests','moroznaya-svezhest-1-2014','Морозная свежесть — 1','blog/moroznaja_svezhest_zombie_farm_prokhozhdenie/2014-12-30-3434','zombie-farm/2014/2/moroznaja-ravnia-1-zombie-farm-mania.png','Временное задание',{'Цели':'Подарить 15 рукавиц коллекции Деда Мороза (пропуск 5 зомбаксов); сделать в Школе любую снежную звезду (2); поколдовать Палочками-выручалочками 50 раз (10).','Награда':'1 Сани Снегурочки.'}),('quests','moroznaya-svezhest-2-2014','Морозная свежесть — 2','blog/moroznaja_svezhest_prokhozhdenie_kvesta_zobie_farm_mania/2014-12-30-3435','zombie-farm/2014/2/moroznaja-ravnia-2-zombie-farm-mania.png','Временное задание',{'Цели':'Найти Сани на складе и поставить на Домашнем; попасть на Морозную равнину. Цели нельзя пропустить.','Награда':'1 Чёрный ящик.'}),('buildings','sani-snegurochki-2014','Сани Снегурочки — Морозная равнина','blog/sani_snegurochki_postrojka_zombie_farm_mania/2014-12-30-3431','zombie-farm/2014/2/Sani-snegurochki-zombie-farm-mania.png','Телепорт',{'Получение':'Награда за первую «Морозную свежесть», нельзя купить или продать.','Переезд':'50 000 монет, 5 снежков, 5 цемента. Возвращаться на Морозную равнину можно в течение 30 дней с момента первого прибытия; другая механика Камина Сказочного леса не переносится автоматически.'}),('buildings','bashnya-moroznoy-ravniny-2014','Башня Морозной равнины','blog/bashnja_na_moroznoj_ravnine_zombie_farm_mania/2014-12-30-3432','zombie-farm/2014/2/bashnya-zombie-mania-farm.png','Постройка острова',{'Функция':'Башню не нужно строить; она позволяет пополнять запас трезубцев до 25 штук каждые 3 минуты для расчистки острова. Это не обязательно 25 новых трезубцев при любом остатке. Купить и продать нельзя; копать под ней нельзя.'}),('buildings','meshok-santy-krasnyy-2014','Мешок Санты — красный','blog/meshok_santy_krasnyi/2014-12-20-3413','zombie-farm/2014/1/meshok-santy-3.png','Сокровище',{'Получение':'Время от времени появляется в Сказочном лесу и открывается на острове; статья также перечисляет Морозную равнину. Купить нельзя.','Оговорка':'Интервал появления и вероятности в статье не установлены. У материала «Ёлочные шарики» красный мешок местами ошибочно подписан зелёным.'}),('materials','novogodnie-shary-2014','Новогодние шары — Морозная равнина','blog/novogodnie_shary_zombie_farm_mania_materialy/2014-12-30-3436','zombie-farm/2014/2/novogodnie-shary-zombie-farm.png','Материал',{'Получение':'На Морозной равнине в мешках Санты и при сносе заснеженных ресурсов. Статья указывает покупку за 3 зомбакса и продажу за 1500 монет.','Использование':'Для строительства двух версий Новогодней ёлки 2014–2015. Не путать с Ёлочным шариком и Ёлочными шариками Сказочного леса. Позже страница дополнена другими сокровищами: это не доказательство их наличия в 2014 году.'}),('materials','trezubets-2014','Трезубец — инструмент островов','blog/trezubec_kopat_gde_vzjat_zombie_farm_mania/2014-10-29-3232','zombie-farm/ZombiFermaMania/Materials_2/trezubec_inventar_zombie_farm_mania.png','Инструмент',{'Получение и применение':'Нельзя купить, по статье появился в октябре 2014; используется для расчистки некоторых островов, включая Кристальный грот и Морозную равнину. На Морозной равнине запас пополняется в Башне.','Версионность':'Поздние ссылки на острова 2016 года не подтверждают их существование в октябре 2014.'}),('buildings','novogodnyaya-elka-2014-zombaksy','Новогодняя ёлка 2014–2015 за зомбаксы','blog/novogodnjaja_elka_2014_2015_za_zombaksy_zombie_farm_mania/2014-12-30-3437','zombie-farm/2014/2/novogodnjaja-elka-zombie-farm.png','Праздничная постройка',{'Покупка':'25 зомбаксов, с 30.12.2014 согласно статье.','Стадии':'20, 65 и 140 Новогодних шаров; всего 225.','Превращение':'Статья перечисляет возможные коллекции и материалы из превращённой ёлки; количества и вероятности не установлены. Нельзя предполагать одновременное выпадение всего списка.'}),('buildings','novogodnyaya-elka-2014-dublony','Новогодняя ёлка 2014–2015 за дублоны','blog/novogodnjaja_elka_2014_2015_za_dublony_zombie_farm_postrojka/2014-12-30-3438','zombie-farm/2014/2/novogodnjaja-elka-zombie-farm.png','Праздничная постройка',{'Покупка':'45 дублонов, с 30.12.2014 согласно статье.','Стадии':'35, 85 и 155 Новогодних шаров; всего 275.','Превращение':'Статья перечисляет возможные коллекции и материалы из превращённой ёлки; количества и вероятности не установлены.'}),('buildings','novogodniy-podarok-ovechka-2014','Новогодний подарок — овечка 2014','blog/novogodnij_podarok/2014-12-20-3414','zombie-farm/2014/1/novogodnij-podarok.png','Подарок',{'Получение':'В статье указано, что подарок от админов выдавался за вход в игру во время новогоднего обновления 2014–2015; нельзя подарить или продать. В шапке статьи дата 20.12.2014.','Возможное содержимое':'Статья перечисляет Зимнюю, Деда Мороза и Ёлочную коллекции, Любовь, Тыкву Z, Барабашку, йодированную соль, монеты и опыт; количества и вероятности не указаны.'})]
